// Generated by Modulo · graph state machine
function divide(a, b) { if (b === 0) throw new Error('Division by zero'); return a / b; }
function modulo(a, b) { if (b === 0) throw new Error('Modulo by zero'); return ((a % b) + b) % b; }
function run(inputs = {}, maxSteps = 10000) {
  const env = Object.create(null), output = [];
  let state = "start";
  for (let step = 0; step < maxSteps; step++) {
    switch (state) {
      case "start": { // start
        state = "read";
        break;
      }
      case "read": { // read
        if (!Object.hasOwn(inputs, "n")) throw new Error('Missing input: n');
        env["n"] = Number(inputs["n"]);
        if (!Number.isFinite(env["n"]) || String(inputs["n"]).trim() === '') throw new Error('Input must be a finite number');
        state = "check";
        break;
      }
      case "check": { // check
        state = (modulo(env["n"], 2) === 0) ? "even" : "odd";
        break;
      }
      case "even": { // even
        output.push("Even");
        state = "end";
        break;
      }
      case "odd": { // odd
        output.push("Odd");
        state = "end";
        break;
      }
      case "end": { // end
        return output;
      }
      default: throw new Error('Unknown flow state');
    }
  }
  throw new Error('Step limit reached; check loop termination');
}
